// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata _tos, uint256[] calldata v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ok;
        try c.transfer(_tos, v) returns (bool returned) {
            ok = true;
            assertTrue(returned == true);
        } catch {
            ok = false;
        }
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address[] memory _tos, uint[] memory v) public returns (bool) {
        require(_tos.length > 0);
        require(v.length == _tos.length);
        bool result = c.transfer(_tos, v);
        assert(msg.sender == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9 || !result);
        return result;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory _tos, uint[] memory v) public payable {
        require(true);
        bool reverted; try c.transfer(_tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory _tos, uint[] memory v) public payable {
        require(true);
        bool reverted;
        try c.transfer(_tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(!reverted || msg.sender != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address[] memory _tos, uint[] memory v) public payable {
        require(address(this).balance >= 0);
        bool reverted;
        address originalCaller = msg.sender;
        try c.transfer(_tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted == (originalCaller != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        try c.transfer(new address[](1), new uint[](1)) { reverted = false; } catch { reverted = true; }
        assert(reverted == (caller == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9));
    }
}
